function AdminNavigation({
  children,
  crumbs,
  displayName,
  initials,
  sections,
  selectedItemId,
  isSideNavCollapsed,
  contentRef,
  onNavItemClick,
  onToggleSideNav,
  onLogout,
}: AdminNavigationProps) {
  return (
    <PageLayoutTopBar
      header={
        <TopbarWithRightNav
          leftSlot={
            <>
              {crumbs.map((crumb, index) => (
                <React.Fragment key={crumb.key}>
                  <Button
                    variant={crumb.variant}
                    size="small"
                    icon={crumb.icon}
                    onClick={crumb.onClick}
                    data-testid={crumb.testId}
                  >
                    {crumb.label}
                  </Button>
                  {index < crumbs.length - 1 && (
                    <FeatherChevronRight className="font-body-2 text-body-2 text-subtext-color" />
                  )}
                </React.Fragment>
              ))}
            </>
          }
          rightSlot={
            <SubframeCore.DropdownMenu.Root>
              <SubframeCore.DropdownMenu.Trigger asChild={true}>
                <button
                  type="button"
                  className="flex h-10 cursor-pointer items-center justify-center gap-2 rounded-rounded-sm border-none bg-default-background px-3.5 shadow-sm"
                  aria-label={`Account menu for ${displayName}`}
                  data-testid="btn-topbar-profile-menu"
                >
                  <Avatar variant="brand" size="small" image="">
                    {initials}
                  </Avatar>
                  <span className="font-button text-button whitespace-nowrap text-neutral-700">
                    {displayName}
                  </span>
                  <FeatherChevronDown className="font-body-2 text-body-2 text-default-font" />
                </button>
              </SubframeCore.DropdownMenu.Trigger>
              <SubframeCore.DropdownMenu.Portal>
                <SubframeCore.DropdownMenu.Content
                  side="bottom"
                  align="end"
                  sideOffset={8}
                  asChild={true}
                  className="z-50"
                >
                  <DropdownMenu>
                    <div className="flex w-full items-center px-4 py-2.5">
                      <span className="font-body-2-bold text-body-2-bold text-neutral-900">
                        {displayName || "—"}
                      </span>
                    </div>
                    <DropdownMenu.DropdownDivider />
                    <DropdownMenu.DropdownItem
                      icon={<FeatherLogOut />}
                      variant="destructive"
                      onClick={onLogout}
                      data-testid="btn-profile-menu-logout"
                    >
                      Log out
                    </DropdownMenu.DropdownItem>
                  </DropdownMenu>
                </SubframeCore.DropdownMenu.Content>
              </SubframeCore.DropdownMenu.Portal>
            </SubframeCore.DropdownMenu.Root>
          }
        />
      }
      sideNav={
        <SideNav
          className="items-stretch overflow-x-hidden overflow-y-auto overscroll-y-contain"
          collapsed={isSideNavCollapsed}
          header={
            <div className="flex w-full items-center justify-between gap-2">
              <Image
                className="h-14 w-auto flex-none object-contain"
                src={LOGO_URL}
                alt="Beroe Max"
                width={120}
                height={56}
                unoptimized={true}
              />
              <IconButton
                variant="outline"
                size="xsmall"
                className="flex-none"
                icon={<FeatherPanelLeft />}
                onClick={onToggleSideNav}
                aria-label="Collapse sidebar"
                title="Collapse sidebar"
                data-testid="btn-sidenav-toggle-collapse"
              />
            </div>
          }
          // Collapsed-state toggle; the expanded-state one lives in `header`.
          topMenu={
            isSideNavCollapsed ? (
              <SideNav.NavItem
                icon={<FeatherPanelLeft />}
                collapsed={true}
                onClick={onToggleSideNav}
                aria-label="Expand sidebar"
                title="Expand sidebar"
                data-testid="btn-sidenav-toggle-collapse"
              />
            ) : null
          }
          mainMenu={
            <>
              {sections.map((section, index) => (
                <React.Fragment key={section.id}>
                  {/* Divider between sections while collapsed (section labels are hidden then). */}
                  {index > 0 && isSideNavCollapsed && (
                    <div className="flex h-px w-full flex-none items-start bg-neutral-200" />
                  )}
                  <SideNav.NavSection label={section.label}>
                    {section.items.map(item => (
                      <SideNav.NavItem
                        key={item.id}
                        icon={NAV_ICONS[item.icon]}
                        selected={item.id === selectedItemId}
                        collapsed={isSideNavCollapsed}
                        onClick={() => onNavItemClick(item)}
                        title={isSideNavCollapsed ? item.label : undefined}
                        data-testid={item.testId}
                      >
                        {item.label}
                      </SideNav.NavItem>
                    ))}
                  </SideNav.NavSection>
                </React.Fragment>
              ))}
            </>
          }
        />
      }
    >
      <div ref={contentRef} className="contents">
        {children}
      </div>
    </PageLayoutTopBar>
  );
}

function AdminNavigationInner({ children }: AdminNavigationLayoutProps) {
  const viewData = useAdminNavigation();
  return <AdminNavigation {...viewData}>{children}</AdminNavigation>;
}

function stripLocale(pathname: string): string {
  return pathname.replace(LOCALE_PREFIX, "");
}

function isWithinPath(pathname: string | null, href: string): boolean {
  if (!pathname) return false;
  const path = stripLocale(pathname);
  return path === href || path.startsWith(`${href}/`);
}

function getSelectedAdminNavItemId(sections: AdminNavSection[], pathname: string | null): string | null {
  const matches = sections
    .flatMap(section => section.items)
    .flatMap(item => (item.href && isWithinPath(pathname, item.href) ? [{ id: item.id, href: item.href }] : []));
  if (matches.length === 0) return null;
  return matches.reduce((best, item) => (item.href.length > best.href.length ? item : best)).id;
}

function isDataLoadsItem(item: AdminNavItem): boolean {
  return item.href === null;
}

function useAdminNavigation(): AdminNavigationViewData {
  const router = useRouter();
  const pathname = usePathname();
  const locale = useLocale();
  const { displayName, initials } = useUserProfile();
  const trail = useBreadcrumbTrail();
  // SideNav collapse/expand, persisted via a `sidenav` query param (same as the CPO frame).
  const [isSideNavCollapsed, toggleSideNavCollapsed] = useSideNavCollapsedUrlSync();

  // "Data Loads" opens the external app's home in a new, signed-in tab.
  const dataLoads = useDataLoadsLauncher({
    onError: () =>
      analyticsService.trackEvent({
        eventType: "open-data-loads-failure",
        eventParams: { source: "sidebar", target: "data-loads-button", action: matomo.ACTION_TYPES.FAILURE },
      }),
  });

  // PageLayoutTopBar scrolls its own internal div, not the window — reset it on
  // every route change, before paint, to avoid a flash of the old position.
  const contentRef = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    let node = contentRef.current?.parentElement ?? null;
    while (node) {
      const style = getComputedStyle(node);
      if (/auto|scroll/.test(style.overflowY) && node.scrollHeight > node.clientHeight) {
        node.scrollTop = 0;
        break;
      }
      node = node.parentElement;
    }
  }, [pathname]);

  const sections = getAdminNavigation();

  const crumbs: AdminBreadcrumbCrumb[] = trail.map((item, index) => {
    const isLast = index === trail.length - 1;
    // Ghost only marks the current page within a nested trail; a single-item
    // trail (a top-level page on its own) is always white.
    const isCurrentNested = isLast && trail.length > 1;
    // A label derived from unloaded API data can be empty — never crash the frame.
    const safeLabel = item.label || "item";
    const href = item.href;
    return {
      key: `${safeLabel}-${href ?? "current"}`,
      label: item.label,
      icon: item.icon,
      variant: isCurrentNested ? "ghost" : "white",
      testId: breadcrumbTestId(safeLabel),
      onClick: !isLast && href
        ? () => {
            analyticsService.trackClick({
              source: "breadcrumbs",
              target: safeLabel,
              action: matomo.ACTION_TYPES.VIEW,
            });
            router.push(href);
          }
        : () => {},
    };
  });

  const onNavItemClick = (item: AdminNavItem) => {
    if (isDataLoadsItem(item)) {
      if (dataLoads.isOpening) return;
      analyticsService.trackClick({ source: "sidebar", target: "data-loads-button", action: matomo.ACTION_TYPES.OPEN });
      dataLoads.open();
      return;
    }
    analyticsService.trackClick({
      source: "sidebar",
      target: `${item.id}-button`,
      action: matomo.ACTION_TYPES.VIEW,
    });
    if (item.href) router.push(item.href);
  };

  const onToggleSideNav = () => {
    analyticsService.trackClick({
      source: "sidebar",
      target: "collapse-toggle",
      action: isSideNavCollapsed ? matomo.ACTION_TYPES.OPEN : matomo.ACTION_TYPES.CLOSE,
    });
    toggleSideNavCollapsed();
  };

  // Same session teardown as v1 (revokes tokens, clears storage, redirects to
  // sign-in), reused via the /logout route.
  const onLogout = () => {
    analyticsService.trackClick({
      source: ANALYTICS_SOURCE,
      target: "logout-button",
      action: matomo.ACTION_TYPES.ACCESS,
    });
    router.push(`/${locale}/logout`);
  };

  return {
    crumbs,
    displayName,
    initials,
    sections,
    selectedItemId: getSelectedAdminNavItemId(sections, pathname),
    isSideNavCollapsed,
    contentRef,
    onNavItemClick,
    onToggleSideNav,
    onLogout,
  };
}
